# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from typing import List, Sequence

from rosterkit.models import Student

def _sort_key(student: Student) -> tuple:
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())

def _chunk(items: Sequence, size: int) -> List[list]:
    return [
        list(items[start:start + size])
        for start in range(0, len(items), size)
    ]

def _row_line(number: int, row: List[Student]) -> str:
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"

# ---
def seating_rows(
    students: Sequence[Student], seats_per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    if seats_per_row <= 0:
        raise ValueError("seats per row must be positive")
    if not students:
        raise ValueError("no students to seat")
    ordered = sorted(students, key=_sort_key)
    rows = _chunk(ordered, seats_per_row)
    return [_row_line(n, r) for n, r in enumerate(rows, 1)]
